# GENERATED by scripts/sync_hems_core.py from hems/core/hems/decision_log.py; do not edit here.
"""Everything needed to follow a decision afterwards (pure): plan segments, the best later opportunities, the
compact full-plan record and a digest of the settings in force.

Three levels of detail build on each other: the decision record says what was chosen and why this quarter, the
segments show the shape of the whole plan, and the plan detail carries every planned quarter with the inputs it
was computed from, so a past plan can be rebuilt and compared line by line.
"""
import hashlib
import json
from dataclasses import asdict, dataclass, is_dataclass
from datetime import datetime, timedelta, tzinfo
from typing import TYPE_CHECKING, Mapping, Sequence

from .battery import Plan, Slot
from .outlook import periods
from .windows import WindowAnalysis, WindowReport
from .slots import SLOT_H

if TYPE_CHECKING:
    from hems.rolling import Decision

QUARTER = timedelta(minutes=15)
ACTION_LETTER = {"charge": "c", "discharge": "d", "idle": "i"}
CODE_LETTER = {"sell": "s", "buy": "b", "hold": "h", "floor": "f", "full": "v", "none": "-"}
MAX_SEGMENTS = 16


def _round(value: float | None, digits: int) -> float | None:
    """Round a value that may be None."""
    return None if value is None else round(value, digits)


def best_later(plan: Plan, slot_start: datetime) -> dict:
    """The best selling and the cheapest buying opportunity after the current quarter, with their time and value.

    These are what 'keep' is waiting for: if the best later sell beats selling now, the plan holds."""
    later = plan.slots[1:]
    sells = [(s.sell_value, i) for i, s in enumerate(later, start=1) if s.sell_value is not None]
    buys = [(s.buy_cost, i) for i, s in enumerate(later, start=1) if s.buy_cost is not None]
    out = {}
    if sells:
        value, i = max(sells)
        out["best_sell_later"] = {"at": (slot_start + i * QUARTER).isoformat(), "value": round(value, 4)}
    if buys:
        value, i = min(buys)
        out["best_buy_later"] = {"at": (slot_start + i * QUARTER).isoformat(), "value": round(value, 4)}
    return out


def plan_segments(plan: Plan, slots: Sequence[Slot], slot_start: datetime, soc0_kwh: float, capacity_kwh: float,
                  limit: int = MAX_SEGMENTS) -> list[dict]:
    """The plan as runs of the same action: from/to, energy, average power and price, SoC at both ends.

    Longer plans are cut at `limit` segments; the last entry then says so."""
    runs: list[list[int]] = []
    for i, planned in enumerate(plan.slots):
        if runs and plan.slots[runs[-1][-1]].action == planned.action:
            runs[-1].append(i)
        else:
            runs.append([i])
    segments = []
    for run in runs[:limit]:
        first, last = run[0], run[-1]
        action = plan.slots[first].action
        energy = sum(abs(plan.slots[i].battery_kwh) for i in run)
        before = plan.slots[first - 1].soc_kwh if first else soc0_kwh
        price = None
        if energy and action != "idle":
            use_import = action == "charge"
            price = sum(abs(plan.slots[i].battery_kwh) * (slots[i].import_price if use_import else slots[i].export_price) for i in run) / energy
        segments.append({"from": (slot_start + first * QUARTER).isoformat(), "to": (slot_start + (last + 1) * QUARTER).isoformat(),
                         "action": action, "kwh": round(energy, 2), "avg_w": round(energy / (len(run) * SLOT_H) * 1000) if action != "idle" else 0,
                         "soc_from_pct": round(before / capacity_kwh * 100, 1), "soc_to_pct": round(plan.slots[last].soc_kwh / capacity_kwh * 100, 1),
                         "avg_price": _round(price, 4)})
    if len(runs) > limit:
        segments.append({"truncated": len(runs) - limit})
    return segments


def plan_detail(decision: "Decision") -> dict:
    """Every planned quarter as compact parallel arrays, with the prices, load and PV the plan was computed from.

    a: action letters (c/d/i), c: reason letters (s sell, b buy, h hold, f floor, v full), w: AC watts (+ charge),
    soc: kWh after the quarter, grid: kWh (+ import), keep/sell/buy: EUR per stored kWh, imp/exp: EUR/kWh,
    load/pv: kWh per quarter. Index i is the quarter starting at `start` + 15 minutes * i."""
    planned = decision.plan.slots
    return {"cycle": decision.slot_start.isoformat(), "start": decision.slot_start.isoformat(), "n": len(planned),
            "a": "".join(ACTION_LETTER[p.action] for p in planned), "c": "".join(CODE_LETTER.get(p.reason_code, "-") for p in planned),
            "w": [round(p.battery_kwh / SLOT_H * 1000) for p in planned], "soc": [round(p.soc_kwh, 2) for p in planned],
            "grid": [round(p.grid_kwh, 3) for p in planned], "keep": [_round(p.stored_value, 4) for p in planned],
            "sell": [_round(p.sell_value, 4) for p in planned], "buy": [_round(p.buy_cost, 4) for p in planned],
            "imp": [round(s.import_price, 4) for s in decision.slots], "exp": [round(s.export_price, 4) for s in decision.slots],
            "load": [round(s.load_kwh, 3) for s in decision.slots], "pv": [round(s.pv_kwh, 3) for s in decision.slots]}


def settings_snapshot(parts: Mapping[str, object]) -> dict:
    """The settings in force and a short hash of them, so a change between two cycles is visible as a new hash."""
    raw = {name: asdict(part) if is_dataclass(part) else str(part) for name, part in parts.items()}
    values = json.loads(json.dumps(raw, default=str))          # dates and other non-JSON values become text once, so the log and the hash agree
    digest = hashlib.sha256(json.dumps(values, sort_keys=True).encode()).hexdigest()[:8]
    return {"hash": digest, "values": values}


# ---- text for the Home Assistant log -------------------------------------------------------------------------

EVENT_VALUE_LIMIT = 160
EVENT_LINE_LIMIT = 700


def when(moment: datetime, reference: datetime, tz: tzinfo) -> str:
    """Local HH:MM; a moment on another local day than `reference` gets '+1d ' (a 48 h plan crosses midnight)."""
    local, ref = moment.astimezone(tz), reference.astimezone(tz)
    days = (local.date() - ref.date()).days
    return f"{local:%H:%M}" if days == 0 else f"{days:+d}d {local:%H:%M}"


STATE_LIMIT = 255                 # Home Assistant refuses a state longer than this
WINDOW_SEPARATOR = " · "
MORE = " …"


@dataclass(frozen=True)
class PlanWords:
    """The words of the plan summary in one language: it is read by the user, unlike the log lines."""
    charge: str
    discharge: str
    tomorrow: str
    nothing: str
    idle: str
    headers: tuple[str, str, str, str, str, str]  # the columns of the table: time, type, power, price, SoC, purpose
    for_sale: str                                 # 'for sale 17:15-19:30': what a charge is for
    peak: str                                     # 'peak 0.489': what a sale is for
    from_stock: str                               # a sale from energy that was in the battery already


PLAN_WORDS = {"en": PlanWords("Charge", "Discharge", "tomorrow", "No charging or discharging planned", "Idle", ("Time", "Type", "Power", "Price", "SoC", "Purpose"),
                              "for sale", "peak", "from stock"),
              "nl": PlanWords("Laden", "Ontladen", "morgen", "Geen laden of ontladen gepland", "Rust", ("Tijd", "Type", "Vermogen", "Prijs", "SoC", "Doel"),
                              "voor verkoop", "piek", "uit voorraad")}


def plan_words(language: str | None) -> PlanWords:
    """The words for a Home Assistant language code ('nl', 'nl-NL'); English when the language is unknown."""
    return PLAN_WORDS.get((language or "en").split("-")[0].lower(), PLAN_WORDS["en"])


def _clock(moment: datetime, start: datetime, tz: tzinfo, words: PlanWords) -> str:
    """Local HH:MM; a moment on a later local day than the plan start gets the day in words ('morgen 02:00', '+2d 02:00')."""
    local = moment.astimezone(tz)
    days = (local.date() - start.astimezone(tz).date()).days
    if days == 0:
        return f"{local:%H:%M}"
    return f"{words.tomorrow if days == 1 else f'{days:+d}d'} {local:%H:%M}"


def _range_text(run: Mapping, start: datetime, tz: tzinfo, words: PlanWords) -> str:
    """'10:45–13:15' in local time; the day is named when the run starts on another day than the plan or ends on another day than it starts."""
    begin, end = datetime.fromisoformat(run["from"]), datetime.fromisoformat(run["to"])
    same_day = begin.astimezone(tz).date() == end.astimezone(tz).date()
    return f"{_clock(begin, start, tz, words)}–{end.astimezone(tz):%H:%M}" if same_day else f"{_clock(begin, start, tz, words)}–{_clock(end, start, tz, words)}"


def plan_summary(segments: Sequence[Mapping], start: datetime, tz: tzinfo, words: PlanWords, limit: int = STATE_LIMIT) -> str:
    """The plan as one readable line for a sensor state: 'Laden 10:45–13:15 · Ontladen 15:45–18:15'.

    Times are local; a window that starts on another day than the plan says so ('Laden morgen 02:00–05:00'). When the
    windows do not fit in `limit` characters the line ends with an ellipsis after the last whole window."""
    windows = periods(segments)
    if not windows:
        return words.nothing
    parts = [f"{words.charge if run['action'] == 'charge' else words.discharge} {_range_text(run, start, tz, words)}" for run in windows]
    cut = any("truncated" in s for s in segments)           # the plan has more runs than the trace carries
    text = WINDOW_SEPARATOR.join(parts)
    while len(text) + (len(MORE) if cut else 0) > limit and len(parts) > 1:
        parts.pop()
        cut = True
        text = WINDOW_SEPARATOR.join(parts)
    return text + (MORE if cut else "")


def plan_table(segments: Sequence[Mapping], start: datetime, tz: tzinfo, words: PlanWords, analysis: WindowAnalysis | None = None) -> str:
    """The plan as a Markdown table for a dashboard card: one row per charge or discharge period, local times.

    What is going on now comes first and is marked 🔴 (also when it is idle, so the table says what happens now); later
    periods are marked ⏰. Columns: time, type, average power, average price, SoC at both ends and, when the window analysis
    is given, the purpose: which sale a charge is for, which peak a sale takes."""
    runs = [s for s in segments if "action" in s]
    found = periods(runs)
    if not found:
        return words.nothing
    rows = [_row(True, runs[0], start, tz, words, "")] if runs[0]["action"] == "idle" else []
    rows += [_row(period["begin"] <= start, period, start, tz, words, _purpose(period, analysis, start, tz, words)) for period in found]
    if any("truncated" in s for s in segments):
        rows.append(["…", "", "", "", "", ""])
    return _table(rows, words)


def _span(report: WindowReport, start: datetime, tz: tzinfo, words: PlanWords) -> str:
    """Where a window is sold ('17:15–19:30'): the sale when the plan has one, the band otherwise."""
    begin, end = (report.sold_from, report.sold_to) if report.sold_from else (report.window.start, report.window.end)
    return _range_text({"from": begin.isoformat(), "to": end.isoformat()}, start, tz, words)


def _purpose(period: Mapping, analysis: WindowAnalysis | None, start: datetime, tz: tzinfo, words: PlanWords) -> str:
    """What a period is for: the sales a charge feeds, or the peak (and the stock) a sale takes; empty without an analysis."""
    if analysis is None:
        return ""
    if period["action"] == "charge":
        fed, moment = set(), period["begin"]
        while moment < period["end"]:
            fed.update(analysis.serves.get(moment, ()))
            moment += QUARTER
        return ", ".join(f"{words.for_sale} {_span(r, start, tz, words)}" for r in analysis.reports if r.window.start in fed)
    inside = [r for r in analysis.reports if r.sold_from and r.sold_from < period["end"] and period["begin"] < r.sold_to]
    return ", ".join(f"{words.peak} {r.window.peak_price:.3f}" + (f" ({words.from_stock})" if r.from_stock_kwh * 2 >= r.sold_kwh else "") for r in inside)


def _row(now: bool, run: Mapping, start: datetime, tz: tzinfo, words: PlanWords, purpose: str) -> list[str]:
    """One table row: the cells of a plan run."""
    kind = {"charge": f"⚡ {words.charge}", "discharge": f"📤 {words.discharge}"}.get(run["action"], f"💤 {words.idle}")
    price = "–" if run["avg_price"] is None else f"€{run['avg_price']:.3f}"
    steady = run["action"] == "idle" or run["soc_from_pct"] == run["soc_to_pct"]          # standby loss moves an idle SoC a little: still one figure
    soc = f"{run['soc_from_pct']:.0f}%" if steady else f"{run['soc_from_pct']:.0f}→{run['soc_to_pct']:.0f}%"
    return [f"{'🔴' if now else '⏰'} {_range_text(run, start, tz, words)}", kind, f"{run['avg_w']} W", price, soc, purpose]


def _table(rows: Sequence[Sequence[str]], words: PlanWords) -> str:
    """Markdown table text: the header of the words, then the rows."""
    lines = ["|" + "|".join(words.headers) + "|", "|" + "|".join("---" for _ in words.headers) + "|"]
    return "\n".join(lines + ["|" + "|".join(cells) + "|" for cells in rows])


def plan_windows(segments: Sequence[Mapping], tz: tzinfo) -> list[dict]:
    """The charge and discharge periods (see outlook.periods) with readable names and local times, for a sensor attribute."""
    return [{"action": s["action"], "from": datetime.fromisoformat(s["from"]).astimezone(tz).isoformat(),
             "to": datetime.fromisoformat(s["to"]).astimezone(tz).isoformat(), "kwh": s["kwh"], "power_w": s["avg_w"],
             "soc_from_pct": s["soc_from_pct"], "soc_to_pct": s["soc_to_pct"], "avg_price_eur_kwh": s["avg_price"]} for s in periods(segments)]


def _compare_text(compare: Mapping, start: datetime, tz: tzinfo) -> str:
    """The sell/keep/buy comparison of the first quarter, with what 'keep' is waiting for."""
    text = f"sell {compare.get('sell')} keep {compare.get('keep')} buy {compare.get('buy')} -> {compare.get('code')}"
    later = compare.get("best_sell_later")
    if later:
        text += f"; best sell later {when(datetime.fromisoformat(later['at']), start, tz)} @{later['value']}"
    return text


def cycle_line(trace: Mapping, tz: tzinfo) -> str:
    """One line per quarter for the Home Assistant log: the decision, why, the prices, and what the plan expects."""
    status = trace.get("status")
    if status != "ok" or "slot_start" not in trace:
        return f"HEMS {status}: no decision this quarter"
    start = datetime.fromisoformat(trace["slot_start"])
    return (f"HEMS {when(start, start, tz)} {status}: {trace.get('first_action')} {trace.get('power_w')} W | soc {trace.get('soc_pct')}% | "
            f"{_compare_text(trace.get('compare') or {}, start, tz)} | import {trace.get('import_price')} export {trace.get('export_price')} | "
            f"{trace.get('horizon_slots')} quarters, prices {trace.get('price_source')} | expected saving {trace.get('expected_saving_eur')} EUR")


def plan_tree(trace: Mapping, tz: tzinfo) -> list[str]:
    """The charge and discharge windows of the whole plan, one line each (idle stretches are the gaps between them)."""
    if "slot_start" not in trace:
        return []
    start = datetime.fromisoformat(trace["slot_start"])
    lines = [f"HEMS plan from {when(start, start, tz)}, {trace.get('horizon_slots')} quarters, expected saving {trace.get('expected_saving_eur')} EUR:"]
    for s in trace.get("segments", []):
        if "truncated" in s:
            lines.append(f"  ... {s['truncated']} more runs")
        elif s["action"] != "idle":
            lines.append(f"  {s['action']:<9} {when(datetime.fromisoformat(s['from']), start, tz)} - {when(datetime.fromisoformat(s['to']), start, tz)}  "
                         f"{s['avg_w']:>5} W  {s['kwh']:>5.1f} kWh  soc {s['soc_from_pct']:.0f}% -> {s['soc_to_pct']:.0f}%  @{s['avg_price']}")
    if len(lines) == 1:
        lines.append("  no charge or discharge planned")
    return lines


def window_tree(trace: Mapping, tz: tzinfo) -> list[str]:
    """The sell windows of the horizon for the Home Assistant log: where each is sold, what it needs, and what the plan does with it."""
    reports = trace.get("windows")
    if not reports or "slot_start" not in trace:
        return []
    start = datetime.fromisoformat(trace["slot_start"])
    at = lambda iso: when(datetime.fromisoformat(iso), start, tz)
    lines = ["HEMS sell windows (what the prices offer; the plan decides):"]
    for w in reports:
        sold = f"sold {at(w['sold_from'])} - {at(w['sold_to'])} {w['sold_kwh']:.1f} kWh" + (f" (stock {w['from_stock_kwh']:.1f})" if w["from_stock_kwh"] else "") if w["sold_from"] \
            else "nothing sold"
        needs = []
        if w["need_fresh"] is not None:
            needs.append(f"after a charge at {at(w['charge_at'])} needs {w['need_fresh']:.3f} ({w['room_fresh']:+.3f})")
        if w["need_replace"] is not None:
            needs.append(f"bought back at {at(w['refill_at'])} needs {w['need_replace']:.3f} ({w['room_replace']:+.3f})")
        if w.get("need_stock") is not None and w["need_fresh"] is None and w["need_replace"] is None:
            needs.append(f"energy in the battery, kept at {w['keep_value']:.3f} per stored kWh, needs {w['need_stock']:.3f} ({w['room_stock']:+.3f})")
        lines.append(f"  {at(w['from'])} - {at(w['to'])} {w['status']:<14} peak {w['peak']:.3f} at {at(w['peak_at'])}; {sold}; {'; '.join(needs)}")
    if trace.get("windows_outside_kwh"):
        lines.append(f"  {trace['windows_outside_kwh']:.1f} kWh sold outside every window")
    return lines


def event_line(event: str, fields: Mapping) -> str:
    """An event as one log line: `HEMS event <name> key=value ...`, each value and the whole line cut to a readable length."""
    def short(value: object) -> str:
        """A value as compact JSON, cut at EVENT_VALUE_LIMIT characters."""
        text = json.dumps(value, separators=(",", ":"), default=str)
        return text if len(text) <= EVENT_VALUE_LIMIT else text[:EVENT_VALUE_LIMIT] + "..."
    line = f"HEMS event {event} " + " ".join(f"{key}={short(value)}" for key, value in fields.items())
    return line if len(line) <= EVENT_LINE_LIMIT else line[:EVENT_LINE_LIMIT] + "..."
